export function classifyError(question,choice){return question.wrongChoiceFeedback?.[choice]?.type||'Unclassified';}
export function sessionAnalytics(session,bank){const map=new Map(bank.map(q=>[q.id,q])),domains={},errors={},pacing=[],skills={};for(const result of session.results){const q=map.get(result.id);if(!q)continue;const domain=domains[q.domain]??={total:0,correct:0,seconds:0,timed:0};if(result.attempts){domain.total++;domain.correct+=Number(result.firstTry);const skill=skills[q.skill]??={total:0,missed:0};skill.total++;skill.missed+=Number(!result.firstTry);}if(Number.isFinite(result.seconds)){domain.seconds+=result.seconds;domain.timed++;pacing.push({id:q.id,skill:q.skill,seconds:result.seconds,target:q.targetSeconds??(q.subject==='Math'?95:71),slow:result.seconds>(q.targetSeconds??(q.subject==='Math'?95:71))*1.25,rushed:!result.firstTry&&result.seconds<15});}for(const attempt of result.responses??[]){if(!attempt.correct){const type=attempt.errorType||classifyError(q,attempt.choice);(errors[type]??=[]).push({id:q.id,skill:q.skill,choice:attempt.choice});}}}const priorities=Object.entries(skills).filter(([,v])=>v.missed).sort((a,b)=>b[1].missed-a[1].missed||b[1].missed/b[1].total-a[1].missed/a[1].total);const worst=priorities[0];const review=worst?`You missed ${worst[1].missed} of ${worst[1].total} ${worst[0]} item${worst[1].total===1?'':'s'} on the first try. Practice that skill first, then retry a similar item.`:'No first-try misses in the attempted items. Keep your next session mixed and check whether that confidence holds on new questions.';return{domains,errors,pacing,slow:pacing.filter(p=>p.slow),rushed:pacing.filter(p=>p.rushed),review,scoredPointsLost:null,disclaimer:'On-device rule-based review. Error types are inferred from selected distractors unless you label them; these are not SAT points.'};}
